llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Ketoconazole, the closest structural analogue sharing the dichlorophenyl-dioxolane, piperazine, aryl ether, and azole core, has a mean oral bioavailability of approximately 75% in healthy volunteers at 200 mg, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Fluconazole, a triazole antifungal, has an absolute oral bioavailability of 94% in healthy volunteers, showing that the azole antifungal scaffold can achieve high oral exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Voriconazole, another triazole antifungal, has a mean absolute oral bioavailability of approximately 96% in adults, reinforcing high F for azole antifungals.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "The highest-transfer analogue MMV367 has an estimated human bioavailability of 90% and shares triazole, aryl ether, and heterocyclic features with the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Suvorexant, which contains a piperazine and multiple aromatic/heteroaromatic rings, has an absolute oral bioavailability of 82% in humans under fasted conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Fenofibrate, despite very high lipophilicity and poor aqueous solubility, has an absolute oral bioavailability of approximately 69% in humans, demonstrating that poor solubility does not preclude F>20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence, especially from structurally related azole antifungals and other piperazine/heteroaromatic drugs, indicates oral bioavailability above 20%. The physicochemical prior is overridden by consistent high-F measurements in analogues, though the query's larger size and higher HBA count leave some uncertainty.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement exists for the exact query molecule.",
    "The closest analogues are smaller and have fewer hydrogen-bond acceptors; the query's higher molecular weight and flexibility may lower absorption.",
    "Food effects and formulation dependence are important for lipophilic azoles and were not assessed for the query.",
    "Some analogue records report lower F in special populations or variable absorption, but these are not representative of typical adult oral dosing."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

